package keys

import (
	"encoding/hex"
	"testing"

	nativefalcon "github.com/aplane-algo/aplane/internal/signing/falcon1024"
)

// frozenNativePQVectors are falcon1024 public keys with the scheme, canonical
// salt and address that key files stored as pq_scheme and pq_address_salt
// before the derivation replaced them (keys imported at 9af76372). Nothing in
// a key file records them any more, so these vectors are what catches a
// change to the derivation.
//
// FROZEN for the falcon1024 key type. A native key type never changes: a
// different scheme, salt rule or address rule is a new key type with its own
// vectors, never an edit to these.
var frozenNativePQVectors = []struct {
	keyType      string
	scheme       string
	salt         byte
	address      string
	publicKeyHex string
}{
	{
		keyType:      "falcon1024",
		scheme:       "f1",
		salt:         0,
		address:      "354G4RT4KU3BMTGFGIN6IBWSXRQ6TB7BNMXLOFECUZMZJEIZVYPPWP6CTA",
		publicKeyHex: "",
	},
	{
		keyType:      "falcon1024",
		scheme:       "f1",
		salt:         1,
		address:      "4Z3OGZHPIQ6WJIELEQOFQ7BNYBVFLFK7RSR4WNRDRWJ3L7OFISNKPN7RPI",
		publicKeyHex: "",
	},
	{
		keyType:      "falcon1024",
		scheme:       "f1",
		salt:         3,
		address:      "5CUXFIJKIXMI2LOOVFWAZ42URHH6IBP3V5L56JNBUT3YEHZWCZ2ZEZV3UE",
		publicKeyHex: "",
	},
	{
		keyType:      "falcon1024",
		scheme:       "f1",
		salt:         5,
		address:      "S3P3SLCCDXIY7VE6DK5GZWRK4D3WDE3MI5QNB5WT5XMSAQTU5RVIMNFHUA",
		publicKeyHex: "",
	},
}

func TestNativePQDerivationMatchesFrozenVectors(t *testing.T) {
	salts := map[byte]bool{}
	for _, vector := range frozenNativePQVectors {
		salts[vector.salt] = true
		publicKey, err := hex.DecodeString(vector.publicKeyHex)
		if err != nil || len(publicKey) != nativefalcon.PublicKeySize {
			t.Fatalf("vector %s public key is not %d bytes of hex", vector.address, nativefalcon.PublicKeySize)
		}
		scheme, err := nativePQScheme(vector.keyType)
		if err != nil || scheme != vector.scheme {
			t.Fatalf("nativePQScheme(%q) = %q, %v; want %q", vector.keyType, scheme, err, vector.scheme)
		}
		salt, address, err := NativePQAddress(vector.keyType, publicKey)
		if err != nil {
			t.Fatalf("NativePQAddress(%s) error = %v", vector.address, err)
		}
		if salt != vector.salt || address.String() != vector.address {
			t.Fatalf("NativePQAddress() = (%d, %s), frozen (%d, %s)", salt, address, vector.salt, vector.address)
		}
	}
	if !salts[0] || len(salts) < 2 {
		t.Fatal("the frozen vectors must cover a zero and a non-zero salt")
	}
}

func TestNativePQDerivationRefusesOtherKeyTypes(t *testing.T) {
	for _, keyType := range []string{"ed25519", "aplane.falcon1024.v1", ""} {
		if _, err := nativePQScheme(keyType); err == nil {
			t.Fatalf("nativePQScheme(%q) accepted a key type that is not native PQ", keyType)
		}
		if _, _, err := NativePQAddress(keyType, make([]byte, nativefalcon.PublicKeySize)); err == nil {
			t.Fatalf("NativePQAddress(%q) accepted a key type that is not native PQ", keyType)
		}
	}
}
